class ExamRoom:
    def __init__(self, n):
        self.n = n
        self.occ = [False] * n

    def seat(self):
        if not any(self.occ):
            self.occ[0] = True
            return 0
        best, bestd = -1, -1
        for i in range(self.n):
            if self.occ[i]:
                continue
            d = self.n
            j = i - 1
            while j >= 0 and not self.occ[j]:
                j -= 1
            d = min(d, i + 1 if j < 0 else i - j)
            j = i + 1
            while j < self.n and not self.occ[j]:
                j += 1
            d = min(d, self.n - i if j >= self.n else j - i)
            if d > bestd:
                bestd, best = d, i
        self.occ[best] = True
        return best

    def leave(self, p):
        self.occ[p] = False

