from sortedcontainers import SortedList

class ExamRoom:
    def __init__(self, n):
        self.n = n
        self.sl = SortedList()

    def seat(self):
        if not self.sl:
            self.sl.add(0)
            return 0
        best, bestd = 0, self.sl[0]
        if self.n - 1 - self.sl[-1] > bestd:
            best, bestd = self.n - 1, self.n - 1 - self.sl[-1]
        for a, b in zip(self.sl, list(self.sl)[1:]):
            d = (b - a) // 2
            if d > bestd:
                best, bestd = a + d, d
        self.sl.add(best)
        return best

    def leave(self, p):
        self.sl.remove(p)

