            bestd = n - 1 - *st.rbegin();
        }
        auto it = st.begin();
        int prev = *it; ++it;
        for (; it != st.end(); ++it) {
            int d = (*it - prev) / 2;
            if (d > bestd) { bestd = d; best = prev + d; }
            prev = *it;
        }
        st.insert(best);
        return best;
    }

    void leave(int p) { st.erase(p); }
private:
    int n;
    set<int> st;
};

