import java.util.TreeSet;

class ExamRoom {
    private int n;
    private TreeSet<Integer> ts = new TreeSet<>();

    public ExamRoom(int n) { this.n = n; }

    public int seat() {
        if (ts.isEmpty()) { ts.add(0); return 0; }
        int best = 0, bestd = ts.first();
        if (n - 1 - ts.last() > bestd) {
            best = n - 1;
            bestd = n - 1 - ts.last();
        }
        Integer prev = null;
        for (int cur : ts) {
            if (prev != null) {
                int d = (cur - prev) / 2;
                if (d > bestd) { bestd = d; best = prev + d; }
            }
            prev = cur;
        }
        ts.add(best);
        return best;
    }

    public void leave(int p) { ts.remove(p); }
}

