var ExamRoom = function(n) {
    this.n = n;
    this.seats = [];
};

ExamRoom.prototype.seat = function() {
    const s = this.seats;
    if (s.length === 0) {
        s.push(0);
        return 0;
    }
    let best = 0, bestd = s[0];
    if (this.n - 1 - s[s.length - 1] > bestd) {
        best = this.n - 1;
        bestd = this.n - 1 - s[s.length - 1];
    }
    for (let i = 1; i < s.length; i++) {
        const d = Math.floor((s[i] - s[i - 1]) / 2);
        if (d > bestd) { bestd = d; best = s[i - 1] + d; }
    }
    let pos = 0;
    while (pos < s.length && s[pos] < best) pos++;
    s.splice(pos, 0, best);
    return best;
};

ExamRoom.prototype.leave = function(p) {
    const idx = this.seats.indexOf(p);
    this.seats.splice(idx, 1);
};
